import React from "react";
import { NavLink } from "react-router-dom";
import { useAuth } from "../../auth/AuthContext";
import { sidebarMenu } from "../../config/sidebarMenu"; // Ensure this path matches where you saved your config!

export default function Sidebar() {
  const { profile } = useAuth();

  // Determine the user's role, defaulting to RESIDENT
  const role = profile?.roles?.name || profile?.role || profile?.user_roles?.role || "RESIDENT";

  // Fetch the correct menu items for this specific role
  const menuItems = sidebarMenu[role] || [];

  return (
    <aside className="w-64 bg-white border-r border-slate-200 h-screen flex flex-col hidden md:flex shrink-0">

      {/* Sidebar Header / Logo Area (Optional, since Navbar has the brand too) */}
      <div className="h-16 flex items-center px-6 border-b border-slate-200">
        <span className="text-sm font-bold text-slate-400 uppercase tracking-widest">
          Menu
        </span>
      </div>

      {/* Dynamic Navigation Links */}
      <nav className="flex-1 overflow-y-auto p-4 space-y-1">
        {menuItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            className={({ isActive }) =>
              `block px-4 py-2.5 rounded-xl text-sm font-semibold transition-colors duration-200 ${
                isActive
                  ? "bg-indigo-50 text-indigo-700 shadow-sm border border-indigo-100"
                  : "text-slate-600 hover:bg-slate-50 hover:text-slate-900"
              }`
            }
          >
            {item.name}
          </NavLink>
        ))}
      </nav>

    </aside>
  );
}
